const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');

const dbPath = path.join(__dirname, 'patchpad.db');
const seedPath = '/assets/incident_seed.json';

let db = new Database(dbPath);

function initializeDatabase() {
  db.exec(`
    CREATE TABLE IF NOT EXISTS documents (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      author TEXT NOT NULL,
      content TEXT NOT NULL,
      currentRevision INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS revisions (
      documentId TEXT NOT NULL,
      revision INTEGER NOT NULL,
      content TEXT NOT NULL,
      timestamp TEXT NOT NULL,
      PRIMARY KEY (documentId, revision),
      FOREIGN KEY (documentId) REFERENCES documents(id)
    );
  `);

  // Load seed data if documents table is empty
  const docCount = db.prepare('SELECT COUNT(*) as count FROM documents').get();
  if (docCount.count === 0) {
    loadSeedData();
  }
}

function loadSeedData() {
  try {
    const seedData = JSON.parse(fs.readFileSync(seedPath, 'utf-8'));
    const doc = seedData.document;

    // Generate full content
    const lines = [...doc.sections];

    // Add generated lines
    for (let i = 1; i <= doc.generatedLineCount; i++) {
      const line = doc.generatedLineTemplate.replace('{n}', i);
      lines.push(line);
    }

    // Add tail sections
    lines.push(...doc.tailSections);

    const content = lines.join('\n');

    // Insert document and first revision
    const now = new Date().toISOString();
    db.prepare(`
      INSERT INTO documents (id, title, author, content, currentRevision)
      VALUES (?, ?, ?, ?, ?)
    `).run(doc.id, doc.title, doc.author, content, 1);

    db.prepare(`
      INSERT INTO revisions (documentId, revision, content, timestamp)
      VALUES (?, ?, ?, ?)
    `).run(doc.id, 1, content, now);

    console.log(`Loaded seed document: ${doc.title}`);
  } catch (err) {
    console.error('Failed to load seed data:', err);
  }
}

function getDocument(id) {
  return db.prepare(`
    SELECT id, title, author, content, currentRevision
    FROM documents WHERE id = ?
  `).get(id);
}

function getAllDocuments() {
  return db.prepare(`
    SELECT id, title, author
    FROM documents
    ORDER BY id
  `).all();
}

function getRevisions(documentId) {
  return db.prepare(`
    SELECT revision, timestamp
    FROM revisions
    WHERE documentId = ?
    ORDER BY revision DESC
  `).all(documentId);
}

function getRevisionContent(documentId, revision) {
  return db.prepare(`
    SELECT content, timestamp
    FROM revisions
    WHERE documentId = ? AND revision = ?
  `).get(documentId, revision);
}

function saveDocument(documentId, newContent, baseRevision) {
  const doc = getDocument(documentId);
  if (!doc) {
    throw new Error(`Document not found: ${documentId}`);
  }

  // Check for stale save
  if (baseRevision !== doc.currentRevision) {
    const err = new Error('Stale save detected');
    err.status = 409;
    throw err;
  }

  // Don't create a new revision if content hasn't changed
  if (newContent === doc.content) {
    return {
      documentId,
      revision: doc.currentRevision,
      status: 'unchanged'
    };
  }

  const newRevision = doc.currentRevision + 1;
  const now = new Date().toISOString();

  const stmt = db.transaction((docId, content, revision, timestamp) => {
    db.prepare(`
      UPDATE documents SET content = ?, currentRevision = ?
      WHERE id = ?
    `).run(content, revision, docId);

    db.prepare(`
      INSERT INTO revisions (documentId, revision, content, timestamp)
      VALUES (?, ?, ?, ?)
    `).run(docId, revision, content, timestamp);
  });

  stmt(documentId, newContent, newRevision, now);

  return {
    documentId,
    revision: newRevision,
    status: 'saved'
  };
}

initializeDatabase();

module.exports = {
  db,
  getDocument,
  getAllDocuments,
  getRevisions,
  getRevisionContent,
  saveDocument
};

const express = require('express');
const path = require('path');
const db = require('./db');

const app = express();
const PORT = process.env.PORT || 3000;

app.use(express.json({ limit: '50mb' }));
app.use(express.static(path.join(__dirname, 'public')));

// Get list of all reports
app.get('/api/reports', (req, res) => {
  try {
    const reports = db.getAllDocuments();
    res.json(reports);
  } catch (err) {
    console.error('Error fetching reports:', err);
    res.status(500).json({ error: 'Failed to fetch reports' });
  }
});

// Get a specific report
app.get('/api/reports/:id', (req, res) => {
  try {
    const doc = db.getDocument(req.params.id);
    if (!doc) {
      return res.status(404).json({ error: 'Report not found' });
    }

    const revisions = db.getRevisions(req.params.id);
    res.json({
      id: doc.id,
      title: doc.title,
      author: doc.author,
      content: doc.content,
      currentRevision: doc.currentRevision,
      revisions
    });
  } catch (err) {
    console.error('Error fetching report:', err);
    res.status(500).json({ error: 'Failed to fetch report' });
  }
});

// Get revision history
app.get('/api/reports/:id/revisions', (req, res) => {
  try {
    const revisions = db.getRevisions(req.params.id);
    res.json(revisions);
  } catch (err) {
    console.error('Error fetching revisions:', err);
    res.status(500).json({ error: 'Failed to fetch revisions' });
  }
});

// Get specific revision content
app.get('/api/reports/:id/revisions/:rev', (req, res) => {
  try {
    const rev = parseInt(req.params.rev, 10);
    if (isNaN(rev)) {
      return res.status(400).json({ error: 'Invalid revision number' });
    }

    const revision = db.getRevisionContent(req.params.id, rev);
    if (!revision) {
      return res.status(404).json({ error: 'Revision not found' });
    }

    res.json(revision);
  } catch (err) {
    console.error('Error fetching revision:', err);
    res.status(500).json({ error: 'Failed to fetch revision' });
  }
});

// Save a report
app.post('/api/reports/:id/save', (req, res) => {
  try {
    const { content, baseRevision, documentId } = req.body;

    // Validate input
    if (typeof content !== 'string') {
      return res.status(400).json({ error: 'Content must be text' });
    }
    if (!Number.isInteger(baseRevision)) {
      return res.status(400).json({ error: 'Base revision must be an integer' });
    }
    if (documentId && documentId !== req.params.id) {
      return res.status(400).json({ error: 'Document ID mismatch' });
    }

    const result = db.saveDocument(req.params.id, content, baseRevision);
    res.json(result);
  } catch (err) {
    if (err.status === 409) {
      return res.status(409).json({
        error: 'Conflict: Document was modified by another tab',
        currentRevision: db.getDocument(req.params.id).currentRevision
      });
    }
    console.error('Error saving report:', err);
    res.status(500).json({ error: 'Failed to save report' });
  }
});

// Serve main app
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

app.listen(PORT, '0.0.0.0', () => {
  console.log(`PatchPad editor listening on http://0.0.0.0:${PORT}`);
});

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --color-bg: #ffffff;
  --color-surface: #f8f9fa;
  --color-border: #e0e3e9;
  --color-text: #1a1a1a;
  --color-text-light: #666;
  --color-text-lighter: #999;
  --color-primary: #0066cc;
  --color-primary-hover: #0052a3;
  --color-primary-light: #e6f0ff;
  --color-success: #28a745;
  --color-error: #dc3545;
  --color-warning: #ffc107;
  --color-highlight: #fff3cd;
  --color-selection: #add6ff;
  --color-caret: #333;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  --font-family-mono: "SF Mono", Monaco, "Cascadia Code", "Roboto Mono", Consolas, monospace;

  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;

  --border-radius: 4px;
  --transition: all 0.15s ease-in-out;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
}

.container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  overflow: hidden;
}

/* Header */
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-lg) var(--spacing-xl);
  border-bottom: 1px solid var(--color-border);
  background-color: var(--color-surface);
  flex-shrink: 0;
}

.header-title h1 {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
}

.author-info {
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.header-status {
  display: flex;
  gap: var(--spacing-lg);
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.save-status {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.save-status.unsaved #statusText::before {
  content: '● ';
  color: var(--color-warning);
}

.save-status.error #statusText::before {
  content: '✗ ';
  color: var(--color-error);
}

#revisionText {
  font-size: 0.75rem;
  color: var(--color-text-lighter);
  margin-top: var(--spacing-xs);
}

/* Toolbar */
.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-md);
  padding: var(--spacing-md) var(--spacing-xl);
  border-bottom: 1px solid var(--color-border);
  background-color: var(--color-surface);
  flex-shrink: 0;
  align-items: center;
}

.toolbar-section {
  display: flex;
  gap: var(--spacing-sm);
  align-items: center;
}

.btn {
  padding: 0.5rem 1rem;
  border: 1px solid var(--color-border);
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
  font-size: 0.875rem;
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
}

.btn:hover:not(:disabled) {
  background-color: var(--color-surface);
  border-color: var(--color-text-lighter);
}

.btn:active:not(:disabled) {
  background-color: var(--color-primary-light);
  border-color: var(--color-primary);
}

.btn-primary {
  background-color: var(--color-primary);
  color: white;
  border-color: var(--color-primary);
}

.btn-primary:hover:not(:disabled) {
  background-color: var(--color-primary-hover);
  border-color: var(--color-primary-hover);
}

.btn-secondary {
  background-color: var(--color-surface);
  border-color: var(--color-border);
}

.btn-secondary:hover:not(:disabled) {
  background-color: #f0f0f0;
}

.btn-sm {
  padding: 0.375rem 0.75rem;
  font-size: 0.8125rem;
}

.btn-close {
  background: none;
  border: none;
  color: var(--color-text-light);
  cursor: pointer;
  font-size: 1.5rem;
  padding: 0;
  width: 2rem;
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.btn-close:hover {
  color: var(--color-text);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.search-input {
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius);
  font-family: var(--font-family);
  font-size: 0.875rem;
  transition: var(--transition);
  min-width: 150px;
}

.search-input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px var(--color-primary-light);
}

.match-count {
  font-size: 0.8rem;
  color: var(--color-text-light);
  margin-left: var(--spacing-sm);
  min-width: 60px;
}

/* Editor Container */
.editor-container {
  display: flex;
  flex: 1;
  min-height: 0;
  gap: var(--spacing-md);
  padding: var(--spacing-md);
  overflow: hidden;
}

.editor-wrapper {
  display: flex;
  flex: 1;
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius);
  overflow: hidden;
  background-color: var(--color-bg);
}

.line-numbers {
  background-color: var(--color-surface);
  border-right: 1px solid var(--color-border);
  padding: var(--spacing-sm) var(--spacing-md);
  text-align: right;
  font-family: var(--font-family-mono);
  font-size: 0.875rem;
  color: var(--color-text-lighter);
  line-height: 1.6;
  user-select: none;
  overflow: hidden;
  min-width: 60px;
  flex-shrink: 0;
}

.editor-content {
  position: relative;
  flex: 1;
  overflow: auto;
  font-family: var(--font-family-mono);
  font-size: 0.875rem;
  line-height: 1.6;
}

.editor-input {
  padding: var(--spacing-md);
  white-space: pre-wrap;
  word-wrap: break-word;
  outline: none;
  caret-color: var(--color-caret);
  color: var(--color-text);
  background-color: transparent;
  font-family: var(--font-family-mono);
  font-size: 0.875rem;
  line-height: 1.6;
  min-height: 100%;
  position: relative;
  z-index: 2;
  resize: none;
  border: none;
  tab-size: 2;
  -moz-tab-size: 2;
}

.editor-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  padding: var(--spacing-md);
  pointer-events: none;
  font-family: var(--font-family-mono);
  font-size: 0.875rem;
  line-height: 1.6;
  color: transparent;
  white-space: pre-wrap;
  word-wrap: break-word;
  z-index: 1;
}

.selection-highlight {
  background-color: var(--color-selection);
}

.find-highlight {
  background-color: var(--color-highlight);
  position: relative;
}

.find-highlight.current {
  background-color: #ffcc00;
  box-shadow: inset 0 0 0 1px #ff9800;
}

.caret {
  position: absolute;
  width: 2px;
  background-color: var(--color-caret);
  height: 1.6em;
  animation: blink 1s infinite;
  z-index: 3;
  pointer-events: none;
}

@keyframes blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

/* History Panel */
.history-panel {
  width: 280px;
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius);
  background-color: var(--color-bg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.history-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-md);
  border-bottom: 1px solid var(--color-border);
  background-color: var(--color-surface);
  flex-shrink: 0;
}

.history-header h3 {
  font-size: 1rem;
  margin: 0;
}

.history-list {
  flex: 1;
  overflow-y: auto;
  padding: var(--spacing-sm);
}

.history-item {
  padding: var(--spacing-md);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius);
  margin-bottom: var(--spacing-sm);
  background-color: var(--color-surface);
  cursor: pointer;
  transition: var(--transition);
}

.history-item:hover {
  background-color: #f0f0f0;
  border-color: var(--color-primary);
}

.history-item-revision {
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
}

.history-item-timestamp {
  font-size: 0.8rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-sm);
}

.history-item-buttons {
  display: flex;
  gap: var(--spacing-sm);
}

.history-item-buttons .btn {
  flex: 1;
  padding: 0.375rem;
  font-size: 0.75rem;
}

/* Status Bar */
.status-bar {
  padding: var(--spacing-md) var(--spacing-xl);
  border-top: 1px solid var(--color-border);
  background-color: var(--color-surface);
  font-size: 0.875rem;
  color: var(--color-text-light);
  min-height: 2rem;
  flex-shrink: 0;
}

/* Modal */
.modal {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.modal-content {
  background-color: var(--color-bg);
  border-radius: var(--border-radius);
  padding: var(--spacing-xl);
  max-width: 500px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.15);
}

.modal-large {
  max-width: 800px;
  max-height: 80vh;
  display: flex;
  flex-direction: column;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--spacing-lg);
}

.modal-header h2 {
  margin: 0;
}

.modal-content h2 {
  margin-bottom: var(--spacing-lg);
}

.modal-content p {
  margin-bottom: var(--spacing-lg);
  color: var(--color-text-light);
  line-height: 1.6;
}

.modal-buttons {
  display: flex;
  gap: var(--spacing-md);
  justify-content: flex-end;
}

.modal-buttons .btn {
  flex: 1;
}

.revision-preview-content {
  flex: 1;
  overflow-y: auto;
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
  background-color: var(--color-surface);
  font-family: var(--font-family-mono);
  font-size: 0.875rem;
  line-height: 1.6;
  white-space: pre-wrap;
  word-wrap: break-word;
  color: var(--color-text);
}

/* Scrollbar styling */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background-color: var(--color-border);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background-color: var(--color-text-lighter);
}

/* Responsive */
@media (max-width: 1280px) {
  .toolbar {
    gap: var(--spacing-sm);
  }

  .toolbar-section {
    gap: var(--spacing-xs);
  }

  .search-input {
    min-width: 120px;
  }

  .history-panel {
    width: 240px;
  }
}

@media (max-width: 768px) {
  .header {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-md);
  }

  .toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .toolbar-section {
    width: 100%;
  }

  .search-input {
    flex: 1;
    min-width: auto;
  }

  .editor-container {
    flex-direction: column;
  }

  .history-panel {
    width: 100%;
    height: 300px;
  }
}

// PatchPad Editor
class TextEditor {
  constructor() {
    this.editorEl = document.getElementById('editor');
    this.overlayEl = document.getElementById('editorOverlay');
    this.lineNumbersEl = document.getElementById('lineNumbers');
    this.statusEl = document.getElementById('statusText');
    this.revisionEl = document.getElementById('revisionText');
    this.cursorInfoEl = document.getElementById('cursorInfo');
    this.saveStatusEl = document.getElementById('saveStatus');

    this.currentDocument = null;
    this.baseRevision = null;
    this.history = [];
    this.historyIndex = -1;
    this.isUndoRedo = false;
    this.lastAction = null;
    this.lastActionTime = 0;
    this.carets = [];
    this.primaryCaretIndex = 0;
    this.selection = null;
    this.findMatches = [];
    this.currentMatchIndex = -1;
    this.isModified = false;
    this.syncInProgress = false;

    this.initializeEventListeners();
    this.loadDocument();
  }

  async loadDocument() {
    try {
      // Check if we have a specific document to load
      const urlParams = new URLSearchParams(window.location.search);
      const docId = urlParams.get('doc') || 'incident-alpha';

      const response = await fetch(`/api/reports/${docId}`);
      if (!response.ok) {
        throw new Error('Failed to load document');
      }

      this.currentDocument = await response.json();
      this.baseRevision = this.currentDocument.currentRevision;

      // Update UI
      document.getElementById('reportTitle').textContent = this.currentDocument.title;
      document.getElementById('authorInfo').textContent = `By ${this.currentDocument.author}`;
      this.revisionEl.textContent = `Revision ${this.currentDocument.currentRevision}`;

      // Set content
      this.editorEl.textContent = this.currentDocument.content;
      this.initializeCaret();
      this.updateLineNumbers();
      this.markSaved();
    } catch (err) {
      console.error('Failed to load document:', err);
      this.showError('Failed to load document');
    }
  }

  initializeCaret() {
    this.carets = [{ offset: 0 }];
    this.primaryCaretIndex = 0;
    this.updateCaretInfo();
  }

  initializeEventListeners() {
    // Editor events
    this.editorEl.addEventListener('input', (e) => this.handleInput(e));
    this.editorEl.addEventListener('keydown', (e) => this.handleKeyDown(e));
    this.editorEl.addEventListener('keyup', (e) => this.handleKeyUp(e));
    this.editorEl.addEventListener('click', (e) => this.handleClick(e));
    this.editorEl.addEventListener('mousedown', (e) => this.handleMouseDown(e));
    this.editorEl.addEventListener('mousemove', (e) => this.handleMouseMove(e));
    this.editorEl.addEventListener('mouseup', (e) => this.handleMouseUp(e));
    this.editorEl.addEventListener('paste', (e) => this.handlePaste(e));

    // Button events
    document.getElementById('saveBtn').addEventListener('click', () => this.save());
    document.getElementById('undoBtn').addEventListener('click', () => this.undo());
    document.getElementById('redoBtn').addEventListener('click', () => this.redo());
    document.getElementById('findNextBtn').addEventListener('click', () => this.findNext());
    document.getElementById('findPrevBtn').addEventListener('click', () => this.findPrev());
    document.getElementById('replaceCurrBtn').addEventListener('click', () => this.replaceCurrent());
    document.getElementById('replaceAllBtn').addEventListener('click', () => this.replaceAll());
    document.getElementById('historyBtn').addEventListener('click', () => this.toggleHistory());
    document.getElementById('closeHistoryBtn').addEventListener('click', () => this.toggleHistory());

    // Find input events
    const findInput = document.getElementById('findInput');
    findInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.shiftKey ? this.findPrev() : this.findNext();
      } else if (e.key === 'Escape') {
        this.editorEl.focus();
      }
    });
    findInput.addEventListener('input', () => this.updateFind());

    // Conflict modal
    document.getElementById('discardBtn').addEventListener('click', () => this.reloadDocument());
    document.getElementById('reloadBtn').addEventListener('click', () => window.location.reload());

    // Load history
    this.loadHistory();
  }

  getText() {
    return this.editorEl.textContent;
  }

  setText(text) {
    this.editorEl.textContent = text;
  }

  getCaretOffset(caret) {
    if (!caret) caret = this.carets[this.primaryCaretIndex];
    const selection = window.getSelection();
    if (selection.rangeCount === 0) return 0;
    const range = selection.getRangeAt(0);
    return this.getOffsetFromNode(this.editorEl, range.startContainer, range.startOffset);
  }

  setCaretOffset(offset, caret) {
    if (!caret) caret = this.carets[this.primaryCaretIndex];
    caret.offset = offset;
    this.syncCaretToDOM();
  }

  getOffsetFromNode(root, node, offset) {
    let totalOffset = 0;
    let walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);

    let currentNode;
    while (currentNode = walker.nextNode()) {
      if (currentNode === node) {
        return totalOffset + offset;
      }
      totalOffset += currentNode.textContent.length;
    }

    return totalOffset;
  }

  getNodeAndOffsetFromOffset(root, targetOffset) {
    let currentOffset = 0;
    let walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);

    let currentNode;
    while (currentNode = walker.nextNode()) {
      const length = currentNode.textContent.length;
      if (currentOffset + length >= targetOffset) {
        return { node: currentNode, offset: targetOffset - currentOffset };
      }
      currentOffset += length;
    }

    const lastNode = this.getLastTextNode(root);
    return { node: lastNode || root, offset: 0 };
  }

  getLastTextNode(root) {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
    let lastNode = null;
    let currentNode;
    while (currentNode = walker.nextNode()) {
      lastNode = currentNode;
    }
    return lastNode;
  }

  syncCaretToDOM() {
    const selection = window.getSelection();
    const primaryCaret = this.carets[this.primaryCaretIndex];
    const { node, offset } = this.getNodeAndOffsetFromOffset(this.editorEl, primaryCaret.offset);

    if (node && node.parentNode) {
      const range = document.createRange();
      range.setStart(node, Math.min(offset, node.textContent.length));
      range.collapse(true);
      selection.removeAllRanges();
      selection.addRange(range);
    }

    this.updateCaretInfo();
  }

  handleInput(e) {
    e.preventDefault();
    const newText = this.editorEl.textContent;
    const oldText = this.history[this.historyIndex]?.text || this.currentDocument.content;

    if (newText === oldText) return;

    this.recordEdit(newText);
    this.updateLineNumbers();
    this.markModified();
    this.updateCaretInfo();
  }

  handleKeyDown(e) {
    const primaryCaret = this.carets[this.primaryCaretIndex];
    const text = this.getText();

    if (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
      e.preventDefault();
      this.insertText('\n');
      return;
    }

    if (e.key === 'Tab') {
      e.preventDefault();
      const indent = e.shiftKey ? this.unindentAtCaret() : '\t';
      if (!e.shiftKey) {
        this.insertText(indent);
      }
      return;
    }

    if (e.key === 'Backspace' && !e.ctrlKey && !e.metaKey) {
      e.preventDefault();
      this.backspace();
      return;
    }

    if (e.key === 'Delete' && !e.ctrlKey && !e.metaKey) {
      e.preventDefault();
      this.delete();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key === 's') {
      e.preventDefault();
      this.save();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key === 'z' && !e.shiftKey) {
      e.preventDefault();
      this.undo();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && (e.key === 'y' || (e.shiftKey && e.key === 'z'))) {
      e.preventDefault();
      this.redo();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
      e.preventDefault();
      document.getElementById('findInput').focus();
      document.getElementById('findInput').select();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key === 'h') {
      e.preventDefault();
      document.getElementById('findInput').focus();
      document.getElementById('replaceInput').focus();
      return;
    }

    if (e.key === 'Escape') {
      e.preventDefault();
      document.getElementById('findInput').focus();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key === 'a') {
      e.preventDefault();
      this.selectAll();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key === 'c') {
      e.preventDefault();
      this.copy();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key === 'x') {
      e.preventDefault();
      this.cut();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key === 'v') {
      e.preventDefault();
      this.paste();
      return;
    }

    // Word navigation
    if ((e.ctrlKey || e.metaKey) && e.key === 'ArrowRight') {
      e.preventDefault();
      this.moveToNextWord(e.shiftKey);
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key === 'ArrowLeft') {
      e.preventDefault();
      this.moveToPrevWord(e.shiftKey);
      return;
    }

    // Home/End
    if (e.key === 'Home') {
      e.preventDefault();
      this.moveToLineStart(e.shiftKey);
      return;
    }

    if (e.key === 'End') {
      e.preventDefault();
      this.moveToLineEnd(e.shiftKey);
      return;
    }

    // Multi-caret support
    if ((e.ctrlKey || e.altKey) && e.key === 'Enter') {
      e.preventDefault();
      this.addCaret();
      return;
    }

    // Arrow keys with shift for selection
    if (e.shiftKey && (e.key === 'ArrowUp' || e.key === 'ArrowDown' || 
        e.key === 'ArrowLeft' || e.key === 'ArrowRight')) {
      return; // Let default behavior handle selection
    }
  }

  handleKeyUp(e) {
    this.updateCaretInfo();
    this.updateFind();
  }

  handleClick(e) {
    if (e.altKey || e.ctrlKey) {
      e.preventDefault();
      this.addCaret();
    }
  }

  handleMouseDown(e) {
    if (e.detail === 3) {
      // Triple click - select line
      e.preventDefault();
      this.selectLine();
    } else if (e.detail === 2) {
      // Double click - select word
      e.preventDefault();
      this.selectWord();
    }
  }

  handleMouseMove(e) {
    // Cursor drag selection
  }

  handleMouseUp(e) {
    this.updateCaretInfo();
  }

  handlePaste(e) {
    e.preventDefault();
    const text = (e.clipboardData || window.clipboardData).getData('text');
    this.insertText(text);
  }

  insertText(text) {
    const oldText = this.getText();
    const primaryCaret = this.carets[this.primaryCaretIndex];
    const offset = primaryCaret.offset;

    const newText = oldText.slice(0, offset) + text + oldText.slice(offset);
    this.setText(newText);
    this.setCaretOffset(offset + text.length, primaryCaret);
    this.syncCaretToDOM();

    this.recordEdit(newText);
    this.updateLineNumbers();
    this.markModified();
  }

  backspace() {
    const text = this.getText();
    const primaryCaret = this.carets[this.primaryCaretIndex];
    if (primaryCaret.offset === 0) return;

    const offset = primaryCaret.offset;
    const before = text.slice(0, offset - 1);
    const after = text.slice(offset);
    const newText = before + after;

    this.setText(newText);
    this.setCaretOffset(offset - 1, primaryCaret);
    this.syncCaretToDOM();

    this.recordEdit(newText);
    this.updateLineNumbers();
    this.markModified();
  }

  delete() {
    const text = this.getText();
    const primaryCaret = this.carets[this.primaryCaretIndex];
    if (primaryCaret.offset >= text.length) return;

    const offset = primaryCaret.offset;
    const before = text.slice(0, offset);
    const after = text.slice(offset + 1);
    const newText = before + after;

    this.setText(newText);
    this.setCaretOffset(offset, primaryCaret);
    this.syncCaretToDOM();

    this.recordEdit(newText);
    this.updateLineNumbers();
    this.markModified();
  }

  selectAll() {
    const text = this.getText();
    this.primaryCaret.offset = 0;
    const range = document.createRange();
    const selection = window.getSelection();
    range.selectNodeContents(this.editorEl);
    selection.removeAllRanges();
    selection.addRange(range);
  }

  selectWord() {
    const text = this.getText();
    const offset = this.carets[this.primaryCaretIndex].offset;

    let start = offset;
    let end = offset;

    while (start > 0 && /\w/.test(text[start - 1])) start--;
    while (end < text.length && /\w/.test(text[end])) end++;

    this.setSelection(start, end);
  }

  selectLine() {
    const text = this.getText();
    const offset = this.carets[this.primaryCaretIndex].offset;

    let start = offset;
    let end = offset;

    while (start > 0 && text[start - 1] !== '\n') start--;
    while (end < text.length && text[end] !== '\n') end++;

    this.setSelection(start, end);
  }

  setSelection(start, end) {
    const { node: startNode, offset: startOffset } = this.getNodeAndOffsetFromOffset(this.editorEl, start);
    const { node: endNode, offset: endOffset } = this.getNodeAndOffsetFromOffset(this.editorEl, end);

    const selection = window.getSelection();
    const range = document.createRange();

    if (startNode && startNode.parentNode && endNode && endNode.parentNode) {
      range.setStart(startNode, Math.min(startOffset, startNode.textContent.length));
      range.setEnd(endNode, Math.min(endOffset, endNode.textContent.length));
      selection.removeAllRanges();
      selection.addRange(range);
    }
  }

  moveToNextWord(select) {
    const text = this.getText();
    let offset = this.carets[this.primaryCaretIndex].offset;

    while (offset < text.length && /\s/.test(text[offset])) offset++;
    while (offset < text.length && /\w/.test(text[offset])) offset++;

    this.carets[this.primaryCaretIndex].offset = offset;
    this.syncCaretToDOM();
  }

  moveToPrevWord(select) {
    const text = this.getText();
    let offset = this.carets[this.primaryCaretIndex].offset;

    if (offset > 0) offset--;
    while (offset > 0 && /\w/.test(text[offset - 1])) offset--;

    this.carets[this.primaryCaretIndex].offset = offset;
    this.syncCaretToDOM();
  }

  moveToLineStart(select) {
    const text = this.getText();
    let offset = this.carets[this.primaryCaretIndex].offset;

    while (offset > 0 && text[offset - 1] !== '\n') offset--;

    this.carets[this.primaryCaretIndex].offset = offset;
    this.syncCaretToDOM();
  }

  moveToLineEnd(select) {
    const text = this.getText();
    let offset = this.carets[this.primaryCaretIndex].offset;

    while (offset < text.length && text[offset] !== '\n') offset++;

    this.carets[this.primaryCaretIndex].offset = offset;
    this.syncCaretToDOM();
  }

  addCaret() {
    const offset = this.getCaretOffset();
    this.carets.push({ offset });
    this.primaryCaretIndex = this.carets.length - 1;
  }

  copy() {
    const selection = window.getSelection();
    if (!selection.toString().length) return;

    const text = selection.toString();
    navigator.clipboard.writeText(text).catch(err => console.error('Copy failed:', err));
  }

  cut() {
    this.copy();
    // Handle deletion of selection
    const text = this.getText();
    const selection = window.getSelection();
    if (selection.toString().length > 0) {
      const range = selection.getRangeAt(0);
      range.deleteContents();
      this.recordEdit(this.getText());
      this.updateLineNumbers();
      this.markModified();
    }
  }

  paste() {
    navigator.clipboard.readText()
      .then(text => this.insertText(text))
      .catch(err => console.error('Paste failed:', err));
  }

  unindentAtCaret() {
    const text = this.getText();
    const primaryCaret = this.carets[this.primaryCaretIndex];
    const offset = primaryCaret.offset;
    const lineStart = text.lastIndexOf('\n', offset - 1) + 1;

    if (offset > lineStart && text[lineStart] === '\t') {
      this.setText(text.slice(0, lineStart) + text.slice(lineStart + 1));
      this.setCaretOffset(offset - 1, primaryCaret);
      this.syncCaretToDOM();
      this.recordEdit(this.getText());
      return '';
    }
    return '\t';
  }

  recordEdit(newText) {
    if (this.isUndoRedo) {
      this.isUndoRedo = false;
      return;
    }

    const now = Date.now();
    const lastEdit = this.history[this.historyIndex];
    const canGroup = lastEdit && (now - this.lastActionTime) < 500 && 
                     this.lastAction === 'typing';

    if (canGroup && this.historyIndex + 1 < this.history.length) {
      // Replace the last grouped edit
      this.historyIndex++;
      this.history[this.historyIndex] = { text: newText };
    } else {
      // Create new history entry
      this.history = this.history.slice(0, this.historyIndex + 1);
      this.history.push({ text: newText });
      this.historyIndex = this.history.length - 1;
    }

    this.lastAction = 'typing';
    this.lastActionTime = now;

    document.getElementById('undoBtn').disabled = this.historyIndex <= 0;
    document.getElementById('redoBtn').disabled = this.historyIndex >= this.history.length - 1;
  }

  undo() {
    if (this.historyIndex > 0) {
      this.historyIndex--;
      this.isUndoRedo = true;
      this.setText(this.history[this.historyIndex].text);
      this.updateLineNumbers();
      this.syncCaretToDOM();
      this.markModified();
      this.updateFind();

      document.getElementById('undoBtn').disabled = this.historyIndex <= 0;
      document.getElementById('redoBtn').disabled = false;
    }
  }

  redo() {
    if (this.historyIndex < this.history.length - 1) {
      this.historyIndex++;
      this.isUndoRedo = true;
      this.setText(this.history[this.historyIndex].text);
      this.updateLineNumbers();
      this.syncCaretToDOM();
      this.markModified();
      this.updateFind();

      document.getElementById('undoBtn').disabled = false;
      document.getElementById('redoBtn').disabled = this.historyIndex >= this.history.length - 1;
    }
  }

  updateLineNumbers() {
    const text = this.getText();
    const lines = text.split('\n').length;
    let lineNumbers = '';
    for (let i = 1; i <= lines; i++) {
      lineNumbers += i + '\n';
    }
    this.lineNumbersEl.textContent = lineNumbers;
  }

  updateCaretInfo() {
    const text = this.getText();
    const selection = window.getSelection();
    let caretPos = 0;

    if (selection.rangeCount > 0) {
      const range = selection.getRangeAt(0);
      caretPos = this.getOffsetFromNode(this.editorEl, range.startContainer, range.startOffset);
    }

    const beforeCaret = text.slice(0, caretPos);
    const lines = beforeCaret.split('\n');
    const lineNum = lines.length;
    const col = lines[lines.length - 1].length + 1;

    this.cursorInfoEl.textContent = `Line ${lineNum}, Column ${col}`;
    this.carets[this.primaryCaretIndex].offset = caretPos;
  }

  updateFind() {
    const query = document.getElementById('findInput').value;
    if (!query) {
      this.findMatches = [];
      this.currentMatchIndex = -1;
      document.getElementById('matchCount').textContent = '';
      return;
    }

    const text = this.getText();
    const regex = new RegExp(this.escapeRegex(query), 'g');
    this.findMatches = [];

    let match;
    while ((match = regex.exec(text)) !== null) {
      this.findMatches.push({ index: match.index, length: match[0].length });
    }

    document.getElementById('matchCount').textContent = 
      `${this.findMatches.length} match${this.findMatches.length !== 1 ? 'es' : ''}`;
  }

  findNext() {
    if (this.findMatches.length === 0) return;

    this.currentMatchIndex = (this.currentMatchIndex + 1) % this.findMatches.length;
    const match = this.findMatches[this.currentMatchIndex];
    this.setSelection(match.index, match.index + match.length);
  }

  findPrev() {
    if (this.findMatches.length === 0) return;

    this.currentMatchIndex = (this.currentMatchIndex - 1 + this.findMatches.length) % this.findMatches.length;
    const match = this.findMatches[this.currentMatchIndex];
    this.setSelection(match.index, match.index + match.length);
  }

  replaceCurrent() {
    if (this.currentMatchIndex === -1 || this.findMatches.length === 0) return;

    const match = this.findMatches[this.currentMatchIndex];
    const replaceText = document.getElementById('replaceInput').value;
    const text = this.getText();

    const newText = text.slice(0, match.index) + replaceText + text.slice(match.index + match.length);
    this.setText(newText);
    this.recordEdit(newText);
    this.updateLineNumbers();
    this.markModified();

    // Update find matches
    this.updateFind();
    if (this.findMatches.length > 0) {
      this.findNext();
    }
  }

  replaceAll() {
    if (this.findMatches.length === 0) return;

    const query = document.getElementById('findInput').value;
    const replaceText = document.getElementById('replaceInput').value;
    let text = this.getText();

    text = text.replace(new RegExp(this.escapeRegex(query), 'g'), replaceText);

    this.setText(text);
    this.recordEdit(text);
    this.updateLineNumbers();
    this.markModified();

    this.updateFind();
  }

  escapeRegex(string) {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  toggleHistory() {
    const panel = document.getElementById('historyPanel');
    if (panel.style.display === 'none') {
      panel.style.display = 'flex';
      this.displayHistory();
    } else {
      panel.style.display = 'none';
    }
  }

  loadHistory() {
    // History is loaded with document
  }

  displayHistory() {
    const historyList = document.getElementById('historyList');
    historyList.innerHTML = '';

    const revisions = this.currentDocument.revisions || [];
    revisions.forEach(rev => {
      const item = document.createElement('div');
      item.className = 'history-item';

      const revNum = document.createElement('div');
      revNum.className = 'history-item-revision';
      revNum.textContent = `Revision ${rev.revision}`;

      const timestamp = document.createElement('div');
      timestamp.className = 'history-item-timestamp';
      const date = new Date(rev.timestamp);
      timestamp.textContent = date.toLocaleString();

      const buttons = document.createElement('div');
      buttons.className = 'history-item-buttons';

      const previewBtn = document.createElement('button');
      previewBtn.className = 'btn btn-sm';
      previewBtn.textContent = 'Preview';
      previewBtn.addEventListener('click', () => this.previewRevision(rev.revision));

      const restoreBtn = document.createElement('button');
      restoreBtn.className = 'btn btn-sm';
      restoreBtn.textContent = 'Restore';
      restoreBtn.addEventListener('click', () => this.restoreRevision(rev.revision));

      buttons.appendChild(previewBtn);
      buttons.appendChild(restoreBtn);

      item.appendChild(revNum);
      item.appendChild(timestamp);
      item.appendChild(buttons);

      historyList.appendChild(item);
    });
  }

  async previewRevision(revision) {
    try {
      const response = await fetch(`/api/reports/${this.currentDocument.id}/revisions/${revision}`);
      const data = await response.json();

      const modal = document.getElementById('previewModal');
      const content = document.getElementById('previewContent');
      content.textContent = data.content;
      modal.style.display = 'flex';
    } catch (err) {
      this.showError('Failed to load revision');
    }
  }

  restoreRevision(revision) {
    const closePreview = () => {
      document.getElementById('previewModal').style.display = 'none';
    };

    // Fetch the revision content
    fetch(`/api/reports/${this.currentDocument.id}/revisions/${revision}`)
      .then(r => r.json())
      .then(data => {
        closePreview();
        this.setText(data.content);
        this.recordEdit(data.content);
        this.updateLineNumbers();
        this.markModified();
        this.initializeCaret();
        this.showMessage(`Restored revision ${revision} as unsaved changes`);
      })
      .catch(err => this.showError('Failed to restore revision'));
  }

  async save() {
    if (this.syncInProgress) return;

    const content = this.getText();
    const currentDoc = this.currentDocument.content;

    if (content === currentDoc) {
      this.showMessage('No changes to save');
      return;
    }

    this.syncInProgress = true;
    document.getElementById('saveBtn').disabled = true;

    try {
      const response = await fetch(`/api/reports/${this.currentDocument.id}/save`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          content,
          baseRevision: this.baseRevision,
          documentId: this.currentDocument.id
        })
      });

      const data = await response.json();

      if (response.status === 409) {
        // Conflict detected
        this.showConflict(data.currentRevision);
        return;
      }

      if (!response.ok) {
        throw new Error(data.error || 'Save failed');
      }

      // Success
      this.currentDocument.currentRevision = data.revision;
      this.baseRevision = data.revision;
      this.currentDocument.content = content;
      this.revisionEl.textContent = `Revision ${data.revision}`;
      this.markSaved();
      this.showMessage('Saved successfully');

      // Reload history
      this.loadDocument();
    } catch (err) {
      this.showError(err.message || 'Save failed');
    } finally {
      this.syncInProgress = false;
      document.getElementById('saveBtn').disabled = false;
    }
  }

  async reloadDocument() {
    try {
      const response = await fetch(`/api/reports/${this.currentDocument.id}`);
      const doc = await response.json();

      this.currentDocument = doc;
      this.baseRevision = doc.currentRevision;
      this.setText(doc.content);
      this.initializeCaret();
      this.updateLineNumbers();
      this.markSaved();

      document.getElementById('conflictModal').style.display = 'none';
      this.showMessage('Document reloaded from server');
    } catch (err) {
      this.showError('Failed to reload document');
    }
  }

  showConflict(serverRevision) {
    this.saveStatusEl.classList.add('error');
    this.statusEl.textContent = 'Conflict: Save rejected';
    document.getElementById('conflictModal').style.display = 'flex';
  }

  markModified() {
    this.isModified = true;
    this.saveStatusEl.classList.add('unsaved');
    this.statusEl.textContent = 'Unsaved changes';
  }

  markSaved() {
    this.isModified = false;
    this.saveStatusEl.classList.remove('unsaved', 'error');
    this.statusEl.textContent = 'Saved';
  }

  showMessage(message) {
    const statusBar = document.getElementById('statusBar');
    statusBar.textContent = message;
    setTimeout(() => {
      if (statusBar.textContent === message) {
        statusBar.textContent = '';
      }
    }, 3000);
  }

  showError(message) {
    const statusBar = document.getElementById('statusBar');
    statusBar.textContent = '✗ ' + message;
    statusBar.style.color = 'var(--color-error)';
    setTimeout(() => {
      statusBar.textContent = '';
      statusBar.style.color = '';
    }, 5000);
  }
}

// Initialize editor
let editor;
document.addEventListener('DOMContentLoaded', () => {
  editor = new TextEditor();
});

function closePreview() {
  document.getElementById('previewModal').style.display = 'none';
}

